    constructor(C _c) { c = _c; }

    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount);
        require(depositAmount > 0);

        c.deposit{value: depositAmount}();

        uint creditBefore = depositAmount;
        uint balBefore = address(c).balance;

        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }

        if (!reverted) {
            (bool ok, bytes memory ret) = address(c).staticcall(abi.encodeWithSignature("credit(address)", address(this)));
