            uint creditAfter = abi.decode(ret, (uint));

            assert(creditAfter == 0 && address(c).balance == balBefore - creditBefore);
        } else {
            assert(address(c).balance >= balBefore - creditBefore);
        }
    }

    receive() external payable {}
}

